INSERT INTO "SecurityGroup" ("Name", "DisplayName") SELECT 'Banking', 'Banking' WHERE NOT EXISTS (SELECT 1 FROM "SecurityGroup" WHERE "Name" = 'Banking');
INSERT INTO "SecurityPermission" ("Name", "DisplayName", "SecurityGroupId") SELECT 'banking.accounts.view', 'View Bank Accounts', g."Id" FROM "SecurityGroup" g WHERE g."Name" = 'Banking' AND NOT EXISTS (SELECT 1 FROM "SecurityPermission" WHERE "Name" = 'banking.accounts.view');
INSERT INTO "SecurityPermission" ("Name", "DisplayName", "SecurityGroupId") SELECT 'banking.accounts.manage', 'Manage Bank Accounts', g."Id" FROM "SecurityGroup" g WHERE g."Name" = 'Banking' AND NOT EXISTS (SELECT 1 FROM "SecurityPermission" WHERE "Name" = 'banking.accounts.manage');
INSERT INTO "SecurityPermission" ("Name", "DisplayName", "SecurityGroupId") SELECT 'banking.transactions.create', 'Create Bank Transactions', g."Id" FROM "SecurityGroup" g WHERE g."Name" = 'Banking' AND NOT EXISTS (SELECT 1 FROM "SecurityPermission" WHERE "Name" = 'banking.transactions.create');
INSERT INTO "SecurityPermission" ("Name", "DisplayName", "SecurityGroupId") SELECT 'banking.reconcile', 'Reconcile Bank Accounts', g."Id" FROM "SecurityGroup" g WHERE g."Name" = 'Banking' AND NOT EXISTS (SELECT 1 FROM "SecurityPermission" WHERE "Name" = 'banking.reconcile');
INSERT INTO "SecurityPermission" ("Name", "DisplayName", "SecurityGroupId") SELECT 'banking.reconcile.undo', 'Undo Bank Reconciliation', g."Id" FROM "SecurityGroup" g WHERE g."Name" = 'Banking' AND NOT EXISTS (SELECT 1 FROM "SecurityPermission" WHERE "Name" = 'banking.reconcile.undo');
INSERT INTO "SecurityRolePermission" ("SecurityRoleId", "SecurityPermissionId") SELECT DISTINCT rp."SecurityRoleId", viewp."Id" FROM "SecurityRolePermission" rp JOIN "SecurityPermission" old ON old."Id" = rp."SecurityPermissionId" JOIN "SecurityPermission" viewp ON viewp."Name" = 'banking.accounts.view' WHERE old."Name" = 'financials.cashbanks.view' AND NOT EXISTS (SELECT 1 FROM "SecurityRolePermission" x WHERE x."SecurityRoleId" = rp."SecurityRoleId" AND x."SecurityPermissionId" = viewp."Id");
INSERT INTO "SecurityRolePermission" ("SecurityRoleId", "SecurityPermissionId") SELECT DISTINCT rp."SecurityRoleId", manage."Id" FROM "SecurityRolePermission" rp JOIN "SecurityPermission" old ON old."Id" = rp."SecurityPermissionId" JOIN "SecurityPermission" manage ON manage."Name" = 'banking.accounts.manage' WHERE old."Name" = 'financials.cashbanks.manage' AND NOT EXISTS (SELECT 1 FROM "SecurityRolePermission" x WHERE x."SecurityRoleId" = rp."SecurityRoleId" AND x."SecurityPermissionId" = manage."Id");
INSERT INTO "SecurityRolePermission" ("SecurityRoleId", "SecurityPermissionId") SELECT DISTINCT rp."SecurityRoleId", tx."Id" FROM "SecurityRolePermission" rp JOIN "SecurityPermission" old ON old."Id" = rp."SecurityPermissionId" JOIN "SecurityPermission" tx ON tx."Name" = 'banking.transactions.create' WHERE old."Name" = 'financials.cashbanks.manage' AND NOT EXISTS (SELECT 1 FROM "SecurityRolePermission" x WHERE x."SecurityRoleId" = rp."SecurityRoleId" AND x."SecurityPermissionId" = tx."Id");
INSERT INTO "SecurityRolePermission" ("SecurityRoleId", "SecurityPermissionId") SELECT DISTINCT rp."SecurityRoleId", recon."Id" FROM "SecurityRolePermission" rp JOIN "SecurityPermission" old ON old."Id" = rp."SecurityPermissionId" JOIN "SecurityPermission" recon ON recon."Name" = 'banking.reconcile' WHERE old."Name" = 'financials.cashbanks.manage' AND NOT EXISTS (SELECT 1 FROM "SecurityRolePermission" x WHERE x."SecurityRoleId" = rp."SecurityRoleId" AND x."SecurityPermissionId" = recon."Id");
INSERT INTO "SecurityRolePermission" ("SecurityRoleId", "SecurityPermissionId") SELECT r."Id", p."Id" FROM "SecurityRole" r, "SecurityPermission" p WHERE r."Name" = 'Accountant' AND p."Name" = 'banking.accounts.view' AND NOT EXISTS (SELECT 1 FROM "SecurityRolePermission" x WHERE x."SecurityRoleId" = r."Id" AND x."SecurityPermissionId" = p."Id");
